  "candidates": [
    {
      "idea": "Aggressive raw‑TTC based full stop with an extended clearance‑hold: when any unmapped point yields TTC < 1.0 s, command an immediate stop and keep the robot halted until the point stays beyond 2.5 m for at least 1 s, ignoring VO and other layers.",
      "new_family": true,
      "for": "prevent collisions when a fast‑approaching object is detected early",
      "risk": "may increase stall time and reduce overall throughput"
    },
    {
      "idea": "Increase reactive‑evasion thresholds: trigger at d < 1.5 m, use back‑up speed 0.8 m/s for 1.0 s, and rotate at up to 1.5 rad/s; also enlarge the cool‑down to avoid repeated triggers.",
      "new_family": false,
      "for": "give the robot more time and distance to separate from the object",
      "risk": "could cause unnecessary stops or overshoot in tight corridors"
    },
    {
      "idea": "Add a raw‑TTC gating layer before the VO planner: scan unmapped points within a ±30° forward cone, compute TTC for each, and if any TTC < 0.8 s force a stop (or short backup) and skip VO; resume VO only after TTC > 1.5 s for 0.5 s.",
      "new_family": true,
      "for": "ensure VO never selects a command that would intersect a fast‑approaching unmapped object",
      "risk": "may increase the number of stop episodes if the TTC threshold is too aggressive"
    }
